{"metadata":{"kernelspec":{"language":"python","display_name":"Python 3","name":"python3"},"language_info":{"name":"python","version":"3.13.15","mimetype":"text/x-python","codemirror_mode":{"name":"ipython","version":3},"pygments_lexer":"ipython3","nbconvert_exporter":"python","file_extension":".py"},"kaggle":{"accelerator":"none","dataSources":[],"dockerImageVersionId":28755,"isInternetEnabled":false,"language":"python","sourceType":"notebook","isGpuEnabled":false}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"import torch\nimport torch.nn as nn\nimport numpy as np \nimport matplotlib.pyplot as plt \nfrom torch.distributions import Normal\n\nX = torch.linspace(5, 85, 400)\nX = X.unsqueeze(1)\n\nprint(X.shape)\n\n#Hydrological params\n\nbaseflow = 12.0\nrunoff_coefficient = 1.2\n\n# Mean discharge (mu)\n\nmean_discharge = baseflow + runoff_coefficient * X\n\n#Uncertainty (sigma)\n\nsigma = 1 + 0.15 * X\n\n# River discharge with gaussian nois \n\nY = mean_discharge + sigma * torch.randn_like(X)\n\n#Model Building\n\nclass StreamFlowUncertaintyModle(nn.Module):\n    \n    def __init__(self) -> None:\n        super().__init__()\n        self.hidden = nn.Linear(1, 64)\n        self.activation = nn.ReLU()\n        self.output_layer = nn.Linear(64, 2)\n\n    def forward(self,x):\n        x = self.hidden(x)\n        x = self.activation(x)\n        out = self.output_layer(x)\n        mu = out[:, 0:1]\n        sigma_raw = out[:, 1:2]\n        sigma = torch.nn.functional.softplus(sigma_raw) + 1e-4\n        return mu, sigma \n              \n\n\n    \nmodel = StreamFlowUncertaintyModle()\n\n#Loss Function\ncriterion = nn.GaussianNLLLoss()\n\noptimizer = torch.optim.Adam(model.parameters(), lr=0.01)\n\nepochs = 800\n\nfor epoch in range(epochs):\n    optimizer.zero_grad()\n    mu_pred, sigma_pred = model(X)\n    loss = criterion(mu_pred, Y, sigma_pred**2)\n    loss.backward()\n    optimizer.step()\n\n    if (epoch + 1) % 50 == 0:\n        print(f\"Epoch [{epoch+1}/{epochs}], Loss: {loss.item():.4f}\")\n\n\n#Evaluation mode\nmodel.eval()\n\nwith torch.no_grad():\n    mu_hat, sigma_hat = model(X)\n\n#Numpy conversion\nmu_pred = mu_hat.numpy()\nsigma_pred = sigma_hat.numpy()\n\n#Final Graph\n\n#plt.figure(figsize=(10, 6))\n\n# plt.scatter(\n#     X.numpy(),\n#     Y.numpy(),\n#     alpha=0.5,\n#     color=\"steelblue\",\n#     label = \"Observed Discharge\",\n# )\n\n# #Predicted Mean\n# plt.plot(\n#     X.numpy(),\n#     mu_pred,\n#     color='crimson',\n#     linewidth=2.5,\n#     label='Model Predicted Mean (μ)',\n# )\n\n\n# #Uncertainty \n\n# plt.fill_between(\n#     X.numpy().squeeze(),\n#     (mu_pred - 2 * sigma_pred).squeeze(),\n#     (mu_pred + 2 * sigma_pred). squeeze(),\n#     color='crimson',\n#     alpha=0.2,\n#     label='Learned Uncertainty (±2σ)',\n# )\n\n\n\n# plt.xlabel(\"Precipitation (mm or l/m²)\")\n# plt.ylabel(\"River Discharge (m³/s)\")\n# plt.title(\"Someșul Mic: Streamflow Discharge with Learned Heteroscedastic Bounds\")\n# plt.legend()\n# plt.grid(True)\n\n# plt.savefig(\n#     \"/kaggle/working/somesul_mic_flood_predictions.png\", dpi=300, bbox_inches=\"tight\"\n# )\n\n# print('Graph was saved succesfully!!!')\n\n\n\nrain_event = torch.tensor([[80.0]])\nflood_threshold = 110.0\n\nmodel.eval()\nwith torch.no_grad():\n    mu_val, sigma_val = model(rain_event)\n\ndist = Normal(loc=mu_val, scale=sigma_val)\n\n#Probability of discharge to pass flood_treshold\nprob_under_threshold = dist.cdf(torch.tensor([flood_threshold]))\nprob_exceedance = 1.0 - prob_under_threshold\n\n#Quantitative resultats\nmu = mu_val.item()\nsigma = sigma_val.item()\nrisk_percent = prob_exceedance.item() * 100\n\n\nprint(f\"\\n--- Flood Scenario: {rain_event.item():.1f} mm precipitation ---\")\nprint(f\"Estimated Mean Discharge (μ): {mu:.2f} m³/s\")\nprint(f\"Associated Uncertainty (σ): {sigma:.2f} m³/s\")\nprint(f\"Critical Levee Threshold: {flood_threshold:.1f} m³/s\")\nprint(f\"Exceedance Probability (Overtopping Risk): {risk_percent:.2f}%\")\n\n\n\n","metadata":{"_uuid":"886fd9a7-634b-40a7-acf2-e1e08788231c","_cell_guid":"b760854c-4b84-423f-a2b8-3e3259788bd6","trusted":true,"collapsed":false,"jupyter":{"outputs_hidden":false},"execution":{"iopub.status.busy":"2026-10-19T18:24:21.461387Z","iopub.execute_input":"2026-10-19T18:24:21.461709Z","iopub.status.idle":"2026-10-19T18:24:22.475168Z","shell.execute_reply.started":"2026-10-19T18:24:21.461685Z","shell.execute_reply":"2026-10-19T18:24:22.474200Z"}},"outputs":[{"name":"stdout","text":"torch.Size([400, 1])\nEpoch [50/800], Loss: 4.3448\nEpoch [100/800], Loss: 4.3156\nEpoch [150/800], Loss: 4.2552\nEpoch [200/800], Loss: 4.0946\nEpoch [250/800], Loss: 3.8658\nEpoch [300/800], Loss: 3.7231\nEpoch [350/800], Loss: 3.6435\nEpoch [400/800], Loss: 3.5526\nEpoch [450/800], Loss: 3.4232\nEpoch [500/800], Loss: 3.2282\nEpoch [550/800], Loss: 3.1515\nEpoch [600/800], Loss: 3.1503\nEpoch [650/800], Loss: 3.1495\nEpoch [700/800], Loss: 3.1484\nEpoch [750/800], Loss: 3.1471\nEpoch [800/800], Loss: 3.1454\n\n--- Flood Scenario: 80.0 mm precipitation ---\nEstimated Mean Discharge (μ): 128.80 m³/s\nAssociated Uncertainty (σ): 35.05 m³/s\nCritical Levee Threshold: 110.0 m³/s\nExceedance Probability (Overtopping Risk): 70.42%\nPonderile au fost salvate în /kaggle/working/somes_uncertainty_model.pth\n","output_type":"stream"}],"execution_count":33}]}